    {\twoline{Points on modular}{hyperbolas (\cref{lem:cilleruelo-garaev})}};
\node[square, fill=blue!4] (bilinear) [xshift=1.75cm][below = 0.4cm of concentration]
    {\twoline{Bilinear Kloosterman}{bounds (\cref{prop:bilinear-freq-concentration})}};
\node[important, fill=blue!9] (large-sieve-exc) [xshift=3cm] [below = 0.4cm of bilinear]
    {\twoline{Large sieve for exceptional Maass}{forms (Thm.\,\ref{thm:large-sieve-freq-concentration} $\Rightarrow$ Thms.\,\ref{thm:large-sieve-expo-phases}, \ref{thm:large-sieve-dispersion-coeffs})}};
\node[square, fill=blue!4] (multilinear) [right = 1.5cm of bilinear]
    {\twoline{Multilinear Kloosterman}{bounds (\cref{cor:kloosterman-averaging-nc,cor:kloosterman-averaging-mnc,cor:kloosterman-averaging-qmnc,cor:kloosterman-incomplete})}};
\node[square, fill=cyan!5] (appl-greatest-prime) [right = 6cm of concentration]
    {\twoline{Applications}{(including \cref{thm:appl-greatest-prime})}};

